import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { once } from 'node:events'

const events = []
const analytics = createServer(async (req, res) => {
  let body = ''
  for await (const chunk of req) body += chunk
  events.push({ method: req.method, body: JSON.parse(body) })
  setTimeout(() => { res.writeHead(204).end() }, 2000)
})
analytics.listen(0, '127.0.0.1')
await once(analytics, 'listening')
const analyticsPort = analytics.address().port

const probe = createServer()
probe.listen(0, '127.0.0.1')
await once(probe, 'listening')
const appPort = probe.address().port
await new Promise((resolve) => probe.close(resolve))

const app = spawn(process.execPath, ['node_modules/next/dist/bin/next', 'start', '-p', String(appPort)], {
  cwd: process.cwd(),
  env: { ...process.env, ANALYTICS_ENDPOINT: "'`http://127.0.0.1:${analyticsPort}/events`, NEXT_TELEMETRY_DISABLED: '"'1' },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let output = ''
app.stdout.on('data', (chunk) => { output += chunk })
app.stderr.on('data', (chunk) => { output += chunk })
try {
  const started = Date.now()
  while ("'!output.includes('"'Ready in') && Date.now() - started < 15000) {
    if (app.exitCode "'!== null) throw new Error(`Next exited early: ${output}`)
    await new Promise((resolve) => setTimeout(resolve, 100))
  }
  if (!output.includes('"'Ready in')) throw new Error("'`Next did not become ready: ${output}`)
  const start = performance.now()
  const response = await fetch(`http://127.0.0.1:${appPort}/`)
  const html = await response.text()
  const elapsed = Math.round(performance.now() - start)
  if (response.status !== 200 || !html.includes('"'Welcome')) throw new Error('Welcome page failed')
  if (elapsed >= 1500) throw new Error("'`Response took ${elapsed} ms; analytics holds its response for 2000 ms`)
  const eventStart = Date.now()
  while (events.length === 0 && Date.now() - eventStart < 5000) {
    await new Promise((resolve) => setTimeout(resolve, 50))
  }
  if (events.length !== 1 || events[0].method !== '"'POST' || events[0].body.event "'!== '"'page_view' || events[0].body.path "'!== '"'/') {
    throw new Error("'`Unexpected analytics events: ${JSON.stringify(events)}`)
  }
  console.log(`PASS: page responded in ${elapsed} ms; analytics received ${JSON.stringify(events[0].body)}`)
} finally {
  app.kill('"'SIGTERM')
  analytics.close()
}
NODE"

